let printAuthorization = null;

function beforeReportPrint() {
  if (globalThis.EduQuestionBankUI?.isPreviewActive?.()) return;
  try {
    if (!printAuthorization || !document.getElementById("printRoot"))
      throw Error("برای چاپ معتبر، از دکمه «چاپ / PDF» گزارش استفاده کنید.");
    if (!fileMode) assertWorkspaceContext(printAuthorization);
    if (busy || drafts.size || draftWritesPending || draftRecoveryFailed)
      throw Error(
        "ثبت اطلاعات کامل نشده است؛ پس از ذخیره، گزارش را دوباره چاپ کنید.",
      );
    return;
  } catch (error) {
    printAuthorization = null;
    document.getElementById("printRoot")?.remove();
    const root = document.createElement("div");
    root.id = "printRoot";
    root.textContent = "چاپ انجام نشد: " + error.message;
    document.body.append(root);
  }
}

function preservePeriodicAppearance(source, copy) {
  const properties = [
    "display",
    "box-sizing",
    "direction",
    "font-family",
    "font-size",
    "font-weight",
    "font-style",
    "line-height",
    "letter-spacing",
    "color",
    "background-color",
    "background-image",
    "text-align",
    "text-decoration",
    "white-space",
    "overflow-wrap",
    "word-break",
    "border-top",
    "border-right",
    "border-bottom",
    "border-left",
    "border-radius",
    "padding",
    "margin",
    "gap",
    "row-gap",
    "column-gap",
    "flex-direction",
    "flex-wrap",
    "flex-grow",
    "flex-shrink",
    "flex-basis",
    "align-items",
    "align-content",
    "align-self",
    "justify-content",
    "grid-column",
    "grid-row",
    "list-style",
    "font-variant-numeric",
  ];
  const originals = [source, ...source.querySelectorAll("*")];
  const clones = [copy, ...copy.querySelectorAll("*")];
  originals.forEach((original, index) => {
    // Embedded grade sheets use the same print rules as the standalone karnameh;
    // copying screen-hidden stage styles would omit the other exam stages.
    if (
      original.closest(
        ".karnameh-student-sheet,.report-session-disclosure,.report-review",
      )
    )
      return;
    const target = clones[index],
      style = getComputedStyle(original);
    for (const property of properties)
      target.style.setProperty(
        property,
        style.getPropertyValue(property),
        "important",
      );
    // Preserve column proportions without fixing a phone/desktop width onto A4.
    if (style.display === "grid") {
      const columns = style.gridTemplateColumns;
      target.style.setProperty(
        "grid-template-columns",
        /^\d/.test(columns) &&
          columns.split(" ").every((value) => /^\d+(\.\d+)?px$/.test(value))
          ? columns
              .split(" ")
              .map((value) => "minmax(0, " + parseFloat(value) + "fr)")
              .join(" ")
          : columns,
        "important",
      );
    }
    target.style.setProperty("print-color-adjust", "exact", "important");
    target.style.setProperty(
      "-webkit-print-color-adjust",
      "exact",
      "important",
    );
  });
  copy.style.setProperty("break-inside", "auto", "important");
  copy.style.setProperty("margin", "0", "important");
  copy.style.setProperty("padding", "0", "important");
  copy.style.setProperty("border", "0", "important");
}

function prepareKarnamehPrint(copy) {
  const originalHeader = copy.querySelector(".karnameh-report-heading");
  if (!originalHeader) return;
  const name = originalHeader.querySelector("h3")?.textContent || "",
    code = copy.dataset.karnamehCode || "—",
    archived = !!copy.querySelector(".karnameh-archived-tag"),
    context = [
      ["مدرسه", copy.dataset.karnamehSchool],
      ["کلاس", copy.dataset.karnamehClass],
      ["سال تحصیلی", copy.dataset.karnamehYear],
    ],
    header = document.createElement("header");
  header.className = "karnameh-print-header";
  header.innerHTML =
    '<div class="karnameh-print-identity"><span class="karnameh-print-kind">کارنامهٔ تحصیلی</span><h2>' +
    esc(name) +
    "</h2><p>کد هنرجو: <bdi>" +
    esc(code) +
    "</bdi>" +
    (archived ? ' <span class="karnameh-print-archive">بایگانی</span>' : "") +
    '</p></div><dl class="karnameh-print-context">' +
    context
      .filter(([, value]) => value)
      .map(
        ([label, value]) =>
          "<div><dt>" + esc(label) + "</dt><dd>" + esc(value) + "</dd></div>",
      )
      .join("") +
    "</dl>";
  originalHeader.replaceWith(header);
  copy.querySelector(".karnameh-student-meta")?.remove();
}

function prepareKarnamehUnitPrintTables(copy) {
  // Keep wide work-unit sheets readable on A4 without changing the live report.
  const trimColumns = (row, start, end, fixed) => {
    let position = 0;
    for (const cell of [...row.cells].slice(fixed)) {
      const next = position + cell.colSpan;
      if (next <= start || position >= end) cell.remove();
      position = next;
    }
  };
  for (const table of copy.querySelectorAll(
    "table.karnameh-unit-competency-table",
  )) {
    const headers = [...(table.tHead?.rows[0]?.cells || [])].slice(1),
      count = headers.length;
    if (count <= 5) continue;
    const section = table.closest(".karnameh-subject-section");
    if (!section) continue;
    const hierarchy = headers.map((cell) => ({
      module: Number(cell.dataset.karnamehModulePosition),
      unit: Number(cell.dataset.karnamehUnitIndex),
    }));
    const hasHierarchy = hierarchy.every(
      (group, index) =>
        Number.isInteger(group.module) &&
        group.module >= 0 &&
        Number.isInteger(group.unit) &&
        group.unit >= 0 &&
        (!index || group.module >= hierarchy[index - 1].module),
    );
    const sections = [];
    for (let start = 0; start < count;) {
      let end = Math.min(start + 5, count);
      if (
        hasHierarchy &&
        end < count &&
        hierarchy[end - 1].module === hierarchy[end].module
      ) {
        let boundary = end;
        while (
          boundary > start &&
          hierarchy[boundary - 1].module === hierarchy[end].module
        )
          boundary--;
        // An oversized module still splits at five, so pagination advances.
        if (boundary > start) end = boundary;
      }
      const part = section.cloneNode(true),
        sheet = part.querySelector("table.karnameh-unit-competency-table");
      for (const [index, row] of [...sheet.tHead.rows].entries())
        trimColumns(row, start * 3, end * 3, index === 0 ? 1 : 0);
      for (const body of sheet.tBodies)
        for (const row of body.rows) trimColumns(row, start * 3, end * 3, 1);
      for (const element of [part, sheet]) {
        element.dataset.karnamehUnitStart = String(start + 1);
        element.dataset.karnamehUnitEnd = String(end);
        element.dataset.karnamehUnitCount = String(end - start);
        if (hasHierarchy) {
          element.dataset.karnamehModuleStart = String(
            hierarchy[start].module + 1,
          );
          element.dataset.karnamehModuleEnd = String(
            hierarchy[end - 1].module + 1,
          );
        }
      }
      const heading = part.querySelector(".karnameh-subject-header h4");
      if (heading) {
        let range =
          "واحدهای " +
          karnamehSheetNumber(start + 1) +
          " تا " +
          karnamehSheetNumber(end);
        if (hasHierarchy) {
          const first = hierarchy[start],
            last = hierarchy[end - 1];
          range =
            first.module === last.module
              ? "پودمان " + karnamehSheetNumber(first.module + 1)
              : "پودمان‌های " +
                karnamehSheetNumber(first.module + 1) +
                " تا " +
                karnamehSheetNumber(last.module + 1);
          if (
            first.module === last.module &&
            ((start > 0 && hierarchy[start - 1].module === first.module) ||
              (end < count && hierarchy[end].module === first.module))
          )
            range +=
              end - start === 1
                ? " · واحد کار " + karnamehSheetNumber(first.unit + 1)
                : " · واحدهای " +
                  karnamehSheetNumber(first.unit + 1) +
                  " تا " +
                  karnamehSheetNumber(last.unit + 1);
        }
        heading.textContent += " · " + range;
      }
      sections.push(part);
      start = end;
    }
    section.replaceWith(...sections);
  }
}

function preparePrint(button) {
  printAuthorization = null;
  document.getElementById("printRoot")?.remove();
  const modal = document.getElementById("modal"),
    isModal = button
      ? button.closest("#modal")
      : !modal.classList.contains("hidden");
  let source = isModal
    ? document.getElementById("modalBody")
    : button?.closest(
        ".report-document,#karnamehTabOutput,#lessonReportTabOutput,#lessonReportOutput,#globalReportOutput,#periodicReportOutput",
      ) ||
      button?.closest(".card") ||
      document.getElementById("karnamehTabOutput") ||
      document.getElementById("lessonReportTabOutput") ||
      document.getElementById("lessonReportOutput") ||
      document.getElementById("globalReportOutput") ||
      document.getElementById("periodicReportOutput") ||
      document.getElementById("app");
  if (!source) throw Error("گزارشی برای چاپ انتخاب نشده است.");
  const copy = source.cloneNode(true);
  const periodic =
    source.matches(".periodic-document") ||
    !!source.querySelector(".periodic-document");
  const karnameh = source.matches(".karnameh-student-sheet");
  if (periodic) preservePeriodicAppearance(source, copy);
  if (karnameh) prepareKarnamehPrint(copy);
  prepareKarnamehUnitPrintTables(copy);
  // Attendance follow-up is a screen disclosure, never a print content filter.
  copy
    .querySelectorAll(
      "details.report-class-group, details.report-session-disclosure, details.report-session-compact, details.report-review, details.report-review-learners",
    )
    .forEach((section) => {
      section.open = true;
      section
        .querySelector(
          ".report-class-body, .report-session-body, .report-session-content, .report-review-body",
        )
        ?.style.setProperty("display", "block", "important");
      // Native details content can fragment as an atomic box in PDF output.
      // Use normal document flow in the print copy, never in the live report.
      const expanded = document.createElement("section");
      for (const attr of [...section.attributes])
        expanded.setAttribute(attr.name, attr.value);
      expanded.dataset.printExpanded = "true";
      expanded.append(...section.childNodes);
      const summary = expanded.querySelector(":scope > summary");
      if (summary) {
        const heading = document.createElement("header");
        for (const attr of [...summary.attributes])
          heading.setAttribute(attr.name, attr.value);
        heading.append(...summary.childNodes);
        summary.replaceWith(heading);
      }
      section.replaceWith(expanded);
    });
  copy
    .querySelectorAll("button,.no-print,form,script,select")
    .forEach((x) => x.remove());
  copy.querySelectorAll("input,textarea").forEach((input) => {
    const span = document.createElement("span");
    span.textContent =
      input.type === "checkbox" ? (input.checked ? "بله" : "خیر") : input.value;
    input.replaceWith(span);
  });
  copy.querySelectorAll("*").forEach((el) => {
    for (const attr of [...el.attributes])
      if (attr.name.startsWith("on") || attr.name === "id")
        el.removeAttribute(attr.name);
    el.style.removeProperty("overflow");
    el.style.removeProperty("overflow-x");
    el.style.removeProperty("overflow-y");
    el.style.removeProperty("max-height");
    el.style.removeProperty("height");
  });
  const root = document.createElement("div");
  root.id = "printRoot";
  if (karnameh) root.className = "karnameh-print-root";
  root.innerHTML =
    periodic || karnameh
      ? ""
      : "<header><h1>گزارش مدرسه</h1><p>" +
        esc(workspace.year + " / " + workspace.term) +
        " · " +
        esc(new Date().toLocaleString("fa-IR")) +
        "</p></header>";
  root.append(copy);
  document.body.append(root);
  const columns = Math.max(
    0,
    ...[...copy.querySelectorAll("tr")].map((tr) =>
      [...tr.children].reduce(
        (sum, cell) => sum + (Number(cell.colSpan) || 1),
        0,
      ),
    ),
  );
  document.getElementById("printPageStyle")?.remove();
  const style = document.createElement("style");
  style.id = "printPageStyle";
  style.textContent =
    "@page { size: A4 " +
    (columns > 8 ? "landscape" : "portrait") +
    "; margin: 12mm; }";
  document.head.append(style);
  return root;
}

async function printReport(button, { context, validate } = {}) {
  try {
    const expected = context || captureWorkspaceContext();
    const scope =
      !context && typeof reportCopyScope === "function"
        ? reportCopyScope()
        : null;
    const sourceConnection =
      typeof connection === "undefined" ? null : connection;
    await document.fonts?.ready;
    await flushDrafts({ strict: true });
    await writer.catch(() => {});
    if (!fileMode) await assertReportSnapshot(expected);
    if (
      button?.isConnected === false ||
      (sourceConnection && connection !== sourceConnection) ||
      (scope !== null && reportCopyScope() !== scope)
    )
      throw Error(
        "صفحه یا محدودهٔ گزارش تغییر کرد؛ گزارش را دوباره برای چاپ انتخاب کنید.",
      );
    if (validate && !validate())
      throw Error(
        "محدوده یا متن گزارش تغییر کرده است؛ گزارش را دوباره تهیه کنید.",
      );
    preparePrint(button);
    printAuthorization = expected;
    if (!globalThis.__EDU_PRINT_TEST__) window.print();
    return true;
  } catch (error) {
    if (context) throw error;
    handleError(error);
    return false;
  }
}
